// Settings for this workflow. Generated by scripts/build_n8n_workflows.py.
return [{ json: {
  "supabase_url": "https://YOUR-PROJECT.supabase.co",
  "approvals_channel": "YOUR-APPROVALS-CHANNEL-ID"
} }];

// The site sends the visitor's private thread link and which button they clicked.
const b = $('Owner action').first().json.body || {};
const token = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(b.token || '') ? b.token : null;
return [{ json: { valid: Boolean(token) && typeof b.approved === 'boolean', token, approved: b.approved === true } }];

// Slack layout for a price waiting for the owner's approval. Pasted into the
// n8n Code nodes by scripts/build_n8n_workflows.py, so workflow 1 (posting
// the draft) and workflow 3 (showing the outcome) always look the same.

function whoLine(lead) {
  const contact = [lead.email, lead.phone].filter(Boolean).join(', ') || 'no contact';
  return `${lead.name || 'Unknown'} (${contact}, zip ${lead.zip || 'unknown'})`;
}

function priceApprovalBlocks(p, outcome) {
  const quote = text => String(text || '').split('\n').map(line => '>' + line).join('\n');
  const blocks = [
    { type: 'section', text: { type: 'mrkdwn', text: `:moneybag: *Price waiting for approval*\n${p.who}\n${p.summary || ''}` } },
    { type: 'section', text: { type: 'mrkdwn', text: `*Draft reply to the customer*\n${quote(p.reply)}` } },
  ];
  if (outcome) {
    blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: outcome }] });
  } else {
    blocks.push({
      type: 'actions',
      elements: [
        { type: 'button', style: 'primary', action_id: 'approve_price', value: String(p.approval_id),
          text: { type: 'plain_text', text: 'Approve and send' } },
        { type: 'button', style: 'danger', action_id: 'reject_price', value: String(p.approval_id),
          text: { type: 'plain_text', text: 'Reject' },
          confirm: {
            title: { type: 'plain_text', text: 'Reject this price?' },
            text: { type: 'mrkdwn', text: 'Nothing is sent to the customer and the lead is handed to you.' },
            confirm: { type: 'plain_text', text: 'Reject' },
            deny: { type: 'plain_text', text: 'Cancel' },
          } },
      ],
    });
  }
  return blocks;
}

// The Slack message for this price: swap its buttons for the outcome.
const config = $('Config').first().json;
const r = $('Resolve approval').first().json;
if (!r.changed || !r.slack_ts) return [];
const outcome = r.status === 'approved'
  ? ':white_check_mark: Approved on the demo site by a visitor playing the owner, and sent to their web thread.'
  : ':x: Rejected on the demo site by a visitor playing the owner. Nothing was sent; the lead was handed off.';
const p = { approval_id: r.approval_id, who: whoLine(r.lead), summary: r.lead.summary, reply: r.reply };
return [{ json: { body: { channel: config.approvals_channel, ts: r.slack_ts, text: outcome,
                          blocks: priceApprovalBlocks(p, outcome) } } }];
